-- Advance only the publication pointer; never rewrite approved content or frozen source identities.
UPDATE plt_dynamic_form_template t
JOIN plt_dynamic_form_template_revision r ON r.id = 993010130467 AND r.template_id = t.id
 AND r.tenant_id = t.tenant_id AND r.status_code = 'PUBLISHED' AND r.deleted = b'0'
SET t.current_published_revision_id = r.id, t.version = t.version + 1,
    t.updater = 'requirement_template_20261013_r6', t.update_time = NOW()
WHERE t.tenant_id = 1 AND t.id = 992203010001 AND t.deleted = b'0'
 AND t.current_published_revision_id = r.source_revision_id;
